for item in lessons:
 m=item['model'];v=m['views']['neutral'];visible=set(m['labelNames'])|set(v.get('points',[]))|set(sum(v.get('segments',[]),[]))
 for name in hidden_initial.get((item['section'],item['level'],item['number']),[]):
  if name=='OB':assert not any(set(e)=={'O','B'} for e in m['edges'])
  else:assert name not in visible

# Equivalent exact input spellings, without numerical evaluation in browser.
for l in lessons:
 ans=l['answer']
 if ans['mode']=='exact':
  values=[]
  for a in ans['accepted']:
   values += [a]
   if a.endswith('.0'):values += [a[:-2]]
   if ';' in a:values += ['('+a+')']
   if 'sqrt' in a:
    values += [a.replace('sqrt(','√('),a.replace('sqrt(','√').replace(')','')]
    import re
    values += [re.sub(r'(?<=\d)sqrt', '*sqrt',a)]
  ans['accepted']=list(dict.fromkeys(values))
assert len(lessons)==60,len(lessons)
assert len(theory)==5
assert len({(x['section'],x['level'],x['number'],x['part']) for x in lessons})==60
# Extend the released records without executing another writer or changing them.
import runpy,sys
extension_dir=pathlib.Path(__file__).with_name('expansion-ch1')
sys.path.insert(0,str(extension_dir))
extension_files=['sections-1-1-1-5.py','section-1-2.py','section-1-3.py','section-1-4-a.py','section-1-4-b.py','section-1-4-c.py']
for filename in extension_files:
 lessons.extend(runpy.run_path(str(extension_dir/filename))['lessons'])
assert len(lessons)==252,len(lessons)
assert len({(x['section'],x['level'],x['number'],x['part']) for x in lessons})==252
for item in lessons+theory:
 assert len(item['steps'])>=3
 for st in item['steps']:assert st['view'] in item['model']['views'],(item.get('number'),st['view'])
 for v in item['model']['views'].values():
  for e in v.get('segments',[]):assert all(p in item['model']['points'] for p in e)
OUT.write_text(json.dumps({'chapter':1,'title':'Отрезки, углы, треугольники','theory':theory,'lessons':lessons},ensure_ascii=False,indent=2)+'\n')
print(OUT, len(lessons),'solved variants',len(theory),'theory modules')
